def word_break(s: str, words: list) -> bool:
    word_set = set(words)
    word_set.discard("")
    if not s:
        return True
    if not word_set:
        return False
    max_len = max(len(w) for w in word_set)
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True
    for i in range(1, n + 1):
        for j in range(max(0, i - max_len), i):
            if dp[j] and s[j:i] in word_set:
                dp[i] = True
                break
    return dp[n]
```

